/// <summary>Repository interface for SynckeyOffsetEntity.</summary>
public partial interface ISynckeyOffsetRepository : IRepository<SynckeyOffsetEntity, DateTimeOffset> { }

/// <summary>Repository interface for SynckeyGuidEntity.</summary>
public partial interface ISynckeyGuidRepository : IRepository<SynckeyGuidEntity, Guid> { }

/// <summary>Repository interface for SynckeyBigintEntity.</summary>
public partial interface ISynckeyBigintRepository : IRepository<SynckeyBigintEntity, long> { }

/// <summary>Repository interface for SynckeyDecimalEntity.</summary>
public partial interface ISynckeyDecimalRepository : IRepository<SynckeyDecimalEntity, decimal> { }

/// <summary>Repository interface for SynckeyVarcharEntity.</summary>
public partial interface ISynckeyVarcharRepository : IRepository<SynckeyVarcharEntity, string> { }

/// <summary>Repository interface for SynckeyNvarcharEntity.</summary>
public partial interface ISynckeyNvarcharRepository : IRepository<SynckeyNvarcharEntity, string> { }

/// <summary>Query extensions: including the whole cascade graph of an entity with a single method call (the read-side counterpart of the graph save - combine it with Where or GetByIdAsync to bound what is fetched), and fetching a single entity by its key.</summary>
/// <remarks>
/// The Include tree of each entity is built once and shared by every query, so it must stay unmodified after construction.
/// </remarks>
public static class SqlQueryExtensions
{
    /// <summary>Includes the cascade graph of SynckeyDatetime2Entity (it has no child-direction navigation, so the query is returned unchanged).</summary>
    public static SqlQuery<SynckeyDatetime2Entity> IncludeGraph(this SqlQuery<SynckeyDatetime2Entity> query) => query;

    /// <summary>Fetches the single entity with the given key - the same key the repository contract's GetByIdAsync takes - and returns null when no row matches.</summary>
    /// <remarks>Combine it with Include or IncludeGraph to fetch that entity together with its graph in one call.</remarks>
    public static Task<SynckeyDatetime2Entity?> GetByIdAsync(
        this SqlQuery<SynckeyDatetime2Entity> query,
        DateTime id,
        CancellationToken cancellationToken = default
    ) => query.Where(entity => entity.KeyAt == id).FirstOrDefaultAsync(cancellationToken);

    /// <summary>Fetches the single entity with the given key, keeping the Include chain written just before it (returns null when no row matches).</summary>
